          "id": "code-ml-19-1-ch19_1_sklearn",
          "title": "Scikit-Learn 1.9: Dominasi Skala Rupiah vs StandardScaler+PCA & Audit Data Leakage Fit(X_all)",
          "language": "python",
          "filename": "19_1_sklearn_scaling_and_leakage.py",
          "code": "import numpy as np\nfrom sklearn.decomposition import PCA\nfrom sklearn.linear_model import LogisticRegression\nfrom sklearn.metrics import roc_auc_score\nfrom sklearn.model_selection import StratifiedKFold, cross_val_score\nfrom sklearn.pipeline import Pipeline\nfrom sklearn.preprocessing import StandardScaler\n\nrng = np.random.default_rng(192)\n\n# A) Bencana Dominasi Skala Fitur: 1 fitur berunit Rupiah (jutaan) vs 6 fitur rasio sinyal [0, 1]\nn = 900\n# 2 faktor risiko laten yang menentukan gagal bayar (default)\nrisk_lat = rng.normal(0.0, 1.0, size=(n, 2))\nratios = np.column_stack([\n    0.45 + 0.14 * risk_lat[:, 0] + rng.normal(0, 0.05, n),   # debt-to-income\n    0.50 + 0.16 * risk_lat[:, 0] + rng.normal(0, 0.05, n),   # card utilization\n    0.35 - 0.12 * risk_lat[:, 1] + rng.normal(0, 0.05, n),   # savings ratio\n    0.60 - 0.15 * risk_lat[:, 1] + rng.normal(0, 0.05, n),   # on-time payment ratio\n    0.40 + 0.11 * (risk_lat[:, 0] - risk_lat[:, 1]) + rng.normal(0, 0.06, n),\n    0.55 + 0.10 * (risk_lat[:, 0] + risk_lat[:, 1]) + rng.normal(0, 0.06, n),\n])\n# Fitur pendapatan berunit Rupiah (10^8) yang hampir murni bising terhadap risiko relatif\nincome_idr = 120_000_000.0 + 45_000_000.0 * rng.normal(0, 1, n)\nX_credit = np.column_stack([income_idr, ratios])\nlogits = 1.6 * risk_lat[:, 0] - 1.3 * risk_lat[:, 1] + rng.normal(0, 0.9, n)\ny_credit = (logits > 0.0).astype(int)\n\ncv = StratifiedKFold(n_splits=5, shuffle=True, random_state=42)\n\npca_unscaled = PCA(n_components=2).fit(X_credit)\npipe_unscaled = Pipeline([\n    (\"pca\", PCA(n_components=2)),\n    (\"clf\", LogisticRegression(C=1.0, max_iter=500)),\n])\npipe_scaled = Pipeline([\n    (\"sc\", StandardScaler()),\n    (\"pca\", PCA(n_components=0.95)),\n    (\"clf\", LogisticRegression(C=1.0, max_iter=500)),\n])\n\nauc_unscaled = float(np.mean(cross_val_score(pipe_unscaled, X_credit, y_credit, cv=cv, scoring=\"roc_auc\")))\nauc_scaled = float(np.mean(cross_val_score(pipe_scaled, X_credit, y_credit, cv=cv, scoring=\"roc_auc\")))\n\nprint(\"=== A. Efek Skala Fitur (Rupiah 10^8 vs Rasio 0..1) pada PCA ===\")\nprint(f\"PCA Tanpa Scaling -> EVR PC1 = {pca_unscaled.explained_variance_ratio_[0]:.6f} | |Loading Rupiah pada PC1| = {abs(pca_unscaled.components_[0, 0]):.6f}\")\nprint(f\"5-Fold CV AUROC | PCA(2) TANPA StandardScaler            = {auc_unscaled:.4f}\")\nprint(f\"5-Fold CV AUROC | Pipeline(StandardScaler + PCA(0.95))   = {auc_scaled:.4f}\")\n\n# B) Bukti Kuantitatif Data Leakage: PCA().fit(X_all) Sebelum Split vs Di Dalam CV\n#    Skenario dimensi tinggi (N=200, d=180) di mana ruang fitur mendekati jumlah sampel\nn_hi, d_hi = 200, 180\nX_hi = rng.normal(0.0, 1.0, size=(n_hi, d_hi))\ny_hi = rng.integers(0, 2, size=n_hi)  # target acak murni (true AUROC = 0.50!)\n\n# Leakage pada Galat Rekonstruksi & Skor Klasifikasi\nkf = StratifiedKFold(n_splits=5, shuffle=True, random_state=42)\nX_all_std = StandardScaler().fit_transform(X_hi)\npca_leaky_all = PCA(n_components=40, random_state=42).fit(X_all_std)\nZ_leaky_all = pca_leaky_all.transform(X_all_std)\n\nrecon_err_leaky, recon_err_honest = [], []\nfor tr_idx, val_idx in kf.split(X_hi, y_hi):\n    # Leaky: basis PCA sudah melihat val_idx saat fit(X_all)!\n    X_val_l = X_all_std[val_idx]\n    X_val_l_hat = pca_leaky_all.inverse_transform(Z_leaky_all[val_idx])\n    recon_err_leaky.append(float(np.mean((X_val_l - X_val_l_hat) ** 2)))\n\n    # Honest: StandardScaler dan PCA di-fit HANYA pada tr_idx!\n    sc_h = StandardScaler().fit(X_hi[tr_idx])\n    X_tr_h = sc_h.transform(X_hi[tr_idx])\n    X_val_h = sc_h.transform(X_hi[val_idx])\n    pca_h = PCA(n_components=40, random_state=42).fit(X_tr_h)\n    X_val_h_hat = pca_h.inverse_transform(pca_h.transform(X_val_h))\n    recon_err_honest.append(float(np.mean((X_val_h - X_val_h_hat) ** 2)))\n\nprint(\"\\n=== B. Audit Leakage: PCA(k=40).fit(X_all) vs Strict In-Fold Fit (N=200, d=180) ===\")\nprint(f\"Mean Validation Recon MSE (LEAKY fit X_all)       = {np.mean(recon_err_leaky):.4f}  <-- Turun palsu karena basis hafal test!\")\nprint(f\"Mean Validation Recon MSE (HONEST fit X_train)    = {np.mean(recon_err_honest):.4f}  <-- Galat out-of-sample sebenarnya!\")\nprint(f\"Underestimasi Galat Akibat Unsupervised Leakage   = {100.0 * (1.0 - np.mean(recon_err_leaky) / np.mean(recon_err_honest)):.2f}%\")",
          "expectedOutput": "=== A. Efek Skala Fitur (Rupiah 10^8 vs Rasio 0..1) pada PCA ===\nPCA Tanpa Scaling -> EVR PC1 = 1.000000 | |Loading Rupiah pada PC1| = 1.000000\n5-Fold CV AUROC | PCA(2) TANPA StandardScaler            = 0.4861\n5-Fold CV AUROC | Pipeline(StandardScaler + PCA(0.95))   = 0.9295\n\n=== B. Audit Leakage: PCA(k=40).fit(X_all) vs Strict In-Fold Fit (N=200, d=180) ===\nMean Validation Recon MSE (LEAKY fit X_all)       = 0.4428  <-- Turun palsu karena basis hafal test!\nMean Validation Recon MSE (HONEST fit X_train)    = 0.7975  <-- Galat out-of-sample sebenarnya!\nUnderestimasi Galat Akibat Unsupervised Leakage   = 44.47%",
          "actualOutput": "=== A. Efek Skala Fitur (Rupiah 10^8 vs Rasio 0..1) pada PCA ===\nPCA Tanpa Scaling -> EVR PC1 = 1.000000 | |Loading Rupiah pada PC1| = 1.000000\n5-Fold CV AUROC | PCA(2) TANPA StandardScaler            = 0.4861\n5-Fold CV AUROC | Pipeline(StandardScaler + PCA(0.95))   = 0.9295\n\n=== B. Audit Leakage: PCA(k=40).fit(X_all) vs Strict In-Fold Fit (N=200, d=180) ===\nMean Validation Recon MSE (LEAKY fit X_all)       = 0.4428  <-- Turun palsu karena basis hafal test!\nMean Validation Recon MSE (HONEST fit X_train)    = 0.7975  <-- Galat out-of-sample sebenarnya!\nUnderestimasi Galat Akibat Unsupervised Leakage   = 44.47%",
