          "id": "code-ml-19-1-ch19_1_diag",
          "title": "Production Audit: Ledakan Noise PCA(whiten=True), Instabilitas Davis-Kahan & Deteksi Anomali",
          "language": "python",
          "filename": "19_1_whitening_daviskahan_anomaly_audit.py",
          "code": "import numpy as np\nfrom sklearn.decomposition import PCA\nfrom sklearn.preprocessing import StandardScaler\n\nrng = np.random.default_rng(193)\n\n# 1) Bahaya PCA(whiten=True) Tanpa Regularisasi Epsilon pada Fitur Kolinear + Drift Uji\nn_tr, n_te = 500, 200\nX_base_tr = rng.normal(0.0, 1.0, size=(n_tr, 4))\n# Fitur ke-5 nyaris kombinasi linier sempurna fitur 0 + fitur 1 (noise mikro 1e-4)\nf_col_tr = X_base_tr[:, 0] + X_base_tr[:, 1] + rng.normal(0.0, 1e-4, size=n_tr)\nX_tr = np.column_stack([X_base_tr, f_col_tr])\n\n# Data produksi mengalami sedikit drift kalibrasi sensor 0.02 pada fitur ke-5\nX_base_te = rng.normal(0.0, 1.0, size=(n_te, 4))\nf_col_te = X_base_te[:, 0] + X_base_te[:, 1] + rng.normal(0.0, 0.02, size=n_te)\nX_te = np.column_stack([X_base_te, f_col_te])\n\nsc = StandardScaler().fit(X_tr)\nX_tr_s, X_te_s = sc.transform(X_tr), sc.transform(X_te)\n\npca_plain = PCA(n_components=5, whiten=False).fit(X_tr_s)\npca_white = PCA(n_components=5, whiten=True).fit(X_tr_s)\n\nZ_te_plain = pca_plain.transform(X_te_s)\nZ_te_white = pca_white.transform(X_te_s)\n\n# ZCA Teregulasi (epsilon=0.05) untuk meredam amplifikasi eigenvalue mikro\nV = pca_plain.components_.T\nlam = pca_plain.explained_variance_\nZ_te_reg_w = (X_te_s @ V) / np.sqrt(lam + 0.05)[None, :]\n\nprint(\"=== 1. Amplifikasi Noise pada PCA(whiten=True) Saat Fitur Kolinear Mengalami Drift 0.02 ===\")\nprint(f\"Eigenvalue terkecil lambda_5 (latih)  = {lam[-1]:.2e}\")\nprint(f\"Test Max |Z| | PCA(whiten=False)      = {np.max(np.abs(Z_te_plain)):8.3f} | Std PC5 = {np.std(Z_te_plain[:, -1]):8.4f}\")\nprint(f\"Test Max |Z| | PCA(whiten=True) RAW   = {np.max(np.abs(Z_te_white)):8.3f} | Std PC5 = {np.std(Z_te_white[:, -1]):8.4f}  <-- MELEDAK!\")\nprint(f\"Test Max |Z| | Whitening Reg eps=0.05 = {np.max(np.abs(Z_te_reg_w)):8.3f} | Std PC5 = {np.std(Z_te_reg_w[:, -1]):8.4f}  <-- STABIL\")\n\n# 2) Instabilitas Sudut Eigenvector Ketika Eigengap Sempit (Hukum Davis-Kahan)\n#    Lambda_1 = 9.0 (terpisah jelas), sedangkan Lambda_2 = 2.05 & Lambda_3 = 1.98 (nyaris kembar!)\ncov_tight = np.diag([9.0, 2.05, 1.98, 0.4, 0.2])\nX_batch1 = rng.multivariate_normal(np.zeros(5), cov_tight, size=600)\nX_batch2 = np.vstack([X_batch1[:570], rng.multivariate_normal(np.zeros(5), cov_tight, size=30)])\n\np1 = PCA(n_components=3).fit(X_batch1)\np2 = PCA(n_components=3).fit(X_batch2)\n\nprint(\"\\n=== 2. Audit Davis-Kahan: Pergeseran 5% Sampel pada Eigengap Lebar vs Sempit ===\")\nfor idx in range(3):\n    cos_sim = abs(float(np.dot(p1.components_[idx], p2.components_[idx])))\n    angle_deg = float(np.degrees(np.arccos(np.clip(cos_sim, 0.0, 1.0))))\n    print(f\"  PC{idx+1} | lambda_b1={p1.explained_variance_[idx]:.3f} | |cos(v_b1, v_b2)|={cos_sim:.4f} | Rotasi={angle_deg:6.2f} derajat\")\n\n# 3) Audit Deteksi Anomali Korelasi via Out-of-Sample Reconstruction Error\n#    Transaksi anomali punya nilai fitur wajar secara marginal, tetapi melanggar hubungan subruang rank-2!\nZ_norm = rng.normal(0.0, 1.0, size=(500, 2))\nW_sub = np.array([[1.2, 0.1], [1.1, 0.2], [0.2, 1.3], [-0.1, 1.2], [0.9, -0.8]])\nX_norm_tr = Z_norm @ W_sub.T + rng.normal(0.0, 0.15, size=(500, 5))\nX_norm_te = rng.normal(0.0, 1.0, size=(100, 2)) @ W_sub.T + rng.normal(0.0, 0.15, size=(100, 5))\n# Anomali: fitur 0 & 1 saling berkebalikan tanda padahal di normal berkorelasi +0.97\nX_anom = np.array([[1.2, -1.2, 0.4, 0.5, 0.0], [-1.0, 1.1, -0.3, -0.4, 0.2]])\n\npca_anom = PCA(n_components=2).fit(X_norm_tr)\nerr_norm = np.sum((X_norm_te - pca_anom.inverse_transform(pca_anom.transform(X_norm_te))) ** 2, axis=1)\nerr_anom = np.sum((X_anom - pca_anom.inverse_transform(pca_anom.transform(X_anom))) ** 2, axis=1)\np99_thresh = float(np.percentile(err_norm, 99))\n\nprint(\"\\n=== 3. PCA Reconstruction Error untuk Deteksi Anomali Pelanggaran Korelasi ===\")\nprint(f\"Normal Test Recon Error  | Mean={np.mean(err_norm):.4f} | p99 Threshold={p99_thresh:.4f}\")\nprint(f\"Anomali Korelasi (2 row) | Errors={[round(float(e), 4) for e in err_anom]} | Terdeteksi (>p99)={int(np.sum(err_anom > p99_thresh))}/2\")",
