          "starterCode": "import numpy as np\n\ndef halko_rsvd_audit(A, k: int, p: int = 4, q: int = 2, seed: int = 42) -> tuple[float, float, bool]:\n    A = np.asarray(A, dtype=float)\n    n, d = A.shape\n    rng = np.random.default_rng(seed)\n    l = min(k + p, min(n, d))\n    # TODO: Stage A (Omega + QR + q power iterations QR) -> Stage B (B = Q^T A, SVD B) -> audit vs SVD eksak\n    pass\n\nrng = np.random.default_rng(192)\nU_s, _ = np.linalg.qr(rng.standard_normal((60, 40)), mode='reduced')\nV_s, _ = np.linalg.qr(rng.standard_normal((40, 40)), mode='reduced')\nsv_s = 12.0 / (np.arange(1, 41) ** 0.75)\nA_s = (U_s * sv_s[None, :]) @ V_s.T\nprint(halko_rsvd_audit(A_s, k=4, p=4, q=2, seed=42))",
