          "id": "code-ml-19-3-ch19_3_diag",
          "title": "Production Audit: Instabilitas init='random', Jebakan Zero-Locking MU & Bencana Shift Min()",
          "language": "python",
          "filename": "19_3_nmf_init_zerolock_shift_audit.py",
          "code": "import numpy as np\nfrom sklearn.decomposition import NMF\nfrom sklearn.preprocessing import StandardScaler\n\nrng = np.random.default_rng(1933)\n\n# Bangun matriks non-negatif berstruktur 6 topik tumpang-tindih (lebih realistis & non-konveks!)\nn, d, k = 300, 30, 6\nH0 = np.zeros((k, d))\nfor c in range(k):\n    idx = (np.arange(c * 5, c * 5 + 8)) % d\n    H0[c, idx] = rng.uniform(0.8, 2.2, size=8)\nW0 = rng.exponential(1.2, size=(n, k)) * (rng.uniform(0, 1, size=(n, k)) > 0.72)\nX = np.maximum(W0 @ H0, 0.0)\n\n# 1) Audit Non-Konveksitas: init='random' (8 seed) vs init='nndsvda' (deterministik)\nrand_errs = []\nfor s in range(8):\n    m = NMF(n_components=k, init=\"random\", solver=\"cd\", max_iter=60, random_state=s).fit(X)\n    rand_errs.append(float(m.reconstruction_err_))\n\nm_nndsvda = NMF(n_components=k, init=\"nndsvda\", solver=\"cd\", max_iter=60, random_state=0).fit(X)\n\nprint(\"=== 1. Stabilitas Non-Konveks: init='random' (8 seed) vs init='nndsvda' ===\")\nprint(f\"init='random' (8 seed) | Min={min(rand_errs):.4f} | Max={max(rand_errs):.4f} | Std={np.std(rand_errs):.4f}\")\nprint(f\"init='nndsvda' (determ)| Err={m_nndsvda.reconstruction_err_:.4f} (deterministik tanpa undian seed!)\")\n\n# 2) Audit Jebakan Zero-Locking pada Multiplicative Updates (init='nndsvd' vs 'nndsvda')\nX_kl = X + rng.poisson(0.15, size=(n, d))\nm_mu_zero = NMF(n_components=k, init=\"nndsvd\", solver=\"mu\", beta_loss=\"kullback-leibler\", max_iter=150, random_state=42).fit(X_kl)\nm_mu_safe = NMF(n_components=k, init=\"nndsvda\", solver=\"mu\", beta_loss=\"kullback-leibler\", max_iter=150, random_state=42).fit(X_kl)\n\nexact_zeros_nndsvd = float(np.mean(m_mu_zero.components_ == 0.0)) * 100.0\nexact_zeros_nndsvda = float(np.mean(m_mu_safe.components_ == 0.0)) * 100.0\n\nprint(\"\\n=== 2. Jebakan Zero-Locking pada Multiplicative Updates (KL-Divergence) ===\")\nprint(f\"MU + init='nndsvd'  | Exact-Zero H={exact_zeros_nndsvd:5.1f}% | KL Recon Err={m_mu_zero.reconstruction_err_:.4f} (banyak nol terkunci!)\")\nprint(f\"MU + init='nndsvda' | Exact-Zero H={exact_zeros_nndsvda:5.1f}% | KL Recon Err={m_mu_safe.reconstruction_err_:.4f} (bebas zero-locking!)\")\n\n# 3) Anti-Pattern: StandardScaler() lalu \"diakali\" dengan X_std - X_std.min() sebelum NMF!\nX_std = StandardScaler().fit_transform(X)\nX_shifted = X_std - X_std.min()  # Semua nol sejati tergusur menjadi konstanta positif!\n\norig_zero_pct = 100.0 * float(np.mean(X == 0.0))\nshift_zero_pct = 100.0 * float(np.mean(X_shifted == 0.0))\n\nnmf_orig = NMF(n_components=k, init=\"nndsvda\", max_iter=250, random_state=42).fit(X)\nnmf_shft = NMF(n_components=k, init=\"nndsvda\", max_iter=250, random_state=42).fit(X_shifted)\n\ndef hoyer(M: np.ndarray) -> float:\n    v = np.abs(M.ravel())\n    return float((np.sqrt(v.size) - np.sum(v) / (np.sqrt(np.sum(v ** 2)) + 1e-12)) / (np.sqrt(v.size) - 1.0))\n\nprint(\"\\n=== 3. Bencana Anti-Pattern: StandardScaler + Shift (X - X.min()) Sebelum NMF ===\")\nprint(f\"Sparsity Nol Sejati X | Data Asli={orig_zero_pct:5.1f}% vs Shifted={shift_zero_pct:5.2f}% (sparsity HANCUR!)\")\nprint(f\"Hoyer Sparsity Basis H| Data Asli={hoyer(nmf_orig.components_):.4f} vs Shifted={hoyer(nmf_shft.components_):.4f} (basis jadi padat!)\")",
          "expectedOutput": "=== 1. Stabilitas Non-Konveks: init='random' (8 seed) vs init='nndsvda' ===\ninit='random' (8 seed) | Min=0.0111 | Max=33.2138 | Std=10.9792\ninit='nndsvda' (determ)| Err=0.0415 (deterministik tanpa undian seed!)\n\n=== 2. Jebakan Zero-Locking pada Multiplicative Updates (KL-Divergence) ===\nMU + init='nndsvd'  | Exact-Zero H= 39.4% | KL Recon Err=66.0208 (banyak nol terkunci!)\nMU + init='nndsvda' | Exact-Zero H=  5.0% | KL Recon Err=49.8862 (bebas zero-locking!)\n\n=== 3. Bencana Anti-Pattern: StandardScaler + Shift (X - X.min()) Sebelum NMF ===\nSparsity Nol Sejati X | Data Asli= 59.2% vs Shifted= 1.67% (sparsity HANCUR!)\nHoyer Sparsity Basis H| Data Asli=0.6178 vs Shifted=0.5517 (basis jadi padat!)",
          "actualOutput": "=== 1. Stabilitas Non-Konveks: init='random' (8 seed) vs init='nndsvda' ===\ninit='random' (8 seed) | Min=0.0111 | Max=33.2138 | Std=10.9792\ninit='nndsvda' (determ)| Err=0.0415 (deterministik tanpa undian seed!)\n\n=== 2. Jebakan Zero-Locking pada Multiplicative Updates (KL-Divergence) ===\nMU + init='nndsvd'  | Exact-Zero H= 39.4% | KL Recon Err=66.0208 (banyak nol terkunci!)\nMU + init='nndsvda' | Exact-Zero H=  5.0% | KL Recon Err=49.8862 (bebas zero-locking!)\n\n=== 3. Bencana Anti-Pattern: StandardScaler + Shift (X - X.min()) Sebelum NMF ===\nSparsity Nol Sejati X | Data Asli= 59.2% vs Shifted= 1.67% (sparsity HANCUR!)\nHoyer Sparsity Basis H| Data Asli=0.6178 vs Shifted=0.5517 (basis jadi padat!)",
