          "code": "import numpy as np\n\nrng = np.random.default_rng(1941)\n\n# 1) Implementasi FastICA Simetris (Hyvarinen & Oja 2000) dari Nol pada Cocktail Party Problem\nn_t = 1200\nt = np.linspace(0.0, 8.0, n_t)\n# 3 sinyal sumber independen non-Gaussian: sinus, gelombang kotak, dan gergaji (sawtooth)\ns1 = np.sin(2.0 * t)\ns2 = np.sign(np.sin(3.3 * t))\ns3 = 2.0 * ((t * 1.4) % 1.0) - 1.0\nS_true = np.column_stack([s1, s2, s3])\nS_true = (S_true - S_true.mean(axis=0)) / S_true.std(axis=0)\n\n# Matriks mixing mikrofon tak ortogonal\nA_mix = np.array([[1.0, 0.7, 0.5], [0.4, 1.2, 0.8], [0.6, -0.5, 1.1]])\nX_obs = S_true @ A_mix.T\n\ndef excess_kurtosis(v: np.ndarray) -> float:\n    vc = v - np.mean(v)\n    var = float(np.mean(vc ** 2)) + 1e-12\n    return float(np.mean(vc ** 4) / (var ** 2) - 3.0)\n\n# Tahap 1: Centering & PCA Whitening\nXc = X_obs - X_obs.mean(axis=0, keepdims=True)\nU, sv, Vt = np.linalg.svd(Xc, full_matrices=False)\nZ_white = (Xc @ Vt.T) / (sv / np.sqrt(n_t))[None, :]  # E[Z^T Z / n] = I\n\n# Tahap 2: FastICA Fixed-Point Newton dengan kontras g(u) = tanh(u) + Dekorelasi Simetris\nW = rng.normal(size=(3, 3))\neig_w, vec_w = np.linalg.eigh(W @ W.T)\nW = vec_w @ np.diag(1.0 / np.sqrt(eig_w)) @ vec_w.T @ W\n\nfor _ in range(100):\n    W_prev = W.copy()\n    WX = W @ Z_white.T                     # (3, n_t)\n    g = np.tanh(WX)                        # g(u) = tanh(u)\n    g_prime = 1.0 - g ** 2                 # g'(u) = sech^2(u)\n    W_new = (g @ Z_white) / n_t - np.mean(g_prime, axis=1, keepdims=True) * W\n    # Dekorelasi simetris: W <- (W W^T)^{-1/2} W\n    ew, vw = np.linalg.eigh(W_new @ W_new.T)\n    W = vw @ np.diag(1.0 / np.sqrt(np.maximum(ew, 1e-12))) @ vw.T @ W_new\n    if np.max(np.abs(np.abs(np.sum(W * W_prev, axis=1)) - 1.0)) < 1e-7:\n        break\n\nS_ica = Z_white @ W.T\n\ndef mean_best_abs_corr(S_est: np.ndarray, S_ref: np.ndarray) -> list[float]:\n    corr_mat = np.abs(np.corrcoef(S_ref.T, S_est.T)[:3, 3:])\n    return [round(float(np.max(corr_mat[j])), 4) for j in range(3)]\n\nprint(\"=== 1. Cocktail Party Separation: PCA Whitening vs FastICA (From Scratch) ===\")\nprint(f\"Excess Kurtosis Sumber Sejati  : {[round(excess_kurtosis(S_true[:, j]), 3) for j in range(3)]}\")\nprint(f\"Excess Kurtosis Campuran X_obs : {[round(excess_kurtosis(X_obs[:, j]), 3) for j in range(3)]}  <-- Lebih Gaussian (CLT!)\")\nprint(f\"Max |Corr| ke Sumber (PCA)     : {mean_best_abs_corr(Z_white, S_true)}  <-- GAGAL pisahkan campuran!\")\nprint(f\"Max |Corr| ke Sumber (FastICA) : {mean_best_abs_corr(S_ica, S_true)}  <-- PULIH >0.999!\")\n\n# 2) Verifikasi Hukum Spektrum Noise Acak Marchenko-Pastur (1967)\nn_mp, d_mp = 600, 200\ngamma = d_mp / n_mp\nsigma2 = 1.0\nlam_minus = sigma2 * (1.0 - np.sqrt(gamma)) ** 2\nlam_plus = sigma2 * (1.0 + np.sqrt(gamma)) ** 2\n\nE_noise = rng.normal(0.0, np.sqrt(sigma2), size=(n_mp, d_mp))\neigs_noise = np.linalg.eigvalsh(np.cov(E_noise, rowvar=False))[::-1]\n\n# Tambahkan tepat 3 sinyal spike rank-3 di atas batas BBP (Baik-Ben Arous-Peche)\nF_sig = rng.normal(0.0, 1.0, size=(n_mp, 3))\nL_sig = rng.normal(0.0, 0.25, size=(d_mp, 3))\nL_sig *= np.array([1.2, 0.95, 0.80])[None, :]\nX_spiked = F_sig @ L_sig.T + E_noise\neigs_spiked = np.linalg.eigvalsh(np.cov(X_spiked, rowvar=False))[::-1]\nk_detected = int(np.sum(eigs_spiked > lam_plus))\n\nprint(f\"\\n=== 2. Hukum Marchenko-Pastur (n={n_mp}, d={d_mp}, gamma={gamma:.3f}, sigma^2=1.0) ===\")\nprint(f\"Batas Teoritis MP        : [lambda_- = {lam_minus:.4f}, lambda_+ = {lam_plus:.4f}]\")\nprint(f\"Matriks Noise Murni      : min={eigs_noise[-1]:.4f}, max={eigs_noise[0]:.4f} (jumlah > lambda_+ = {int(np.sum(eigs_noise > lam_plus))})\")\nprint(f\"Matriks + 3 Spike Sinyal : Top-5 eig={[round(float(x), 3) for x in eigs_spiked[:5]]} -> Terdeteksi k_MP = {k_detected}/3!\")",
