          "starterCode": "import numpy as np\n\ndef mp_denoise_and_kurtosis(X, y_signal, sigma2: float = 1.0) -> tuple[float, int, float, float]:\n    X = np.asarray(X, dtype=float)\n    y = np.asarray(y_signal, dtype=float)\n    n, d = X.shape\n    # TODO: hitung lam_plus Marchenko-Pastur, jumlah eigenvalue > lam_plus (k_mp), sig_var_ratio, dan excess kurtosis y\n    pass\n\nrng = np.random.default_rng(194)\nF_s = rng.normal(0.0, 1.0, size=(200, 2))\nL_s = rng.normal(0.0, 0.35, size=(50, 2))\nX_s = F_s @ L_s.T + rng.normal(0.0, 1.0, size=(200, 50))\ny_s = np.sign(np.sin(np.linspace(0.0, 12.0, 200)))\nprint(mp_denoise_and_kurtosis(X_s, y_s, sigma2=1.0))",
